t = int(input())
for _ in range(t):
	k = int(input())
	s = list(input())
	if k == 1 or len(s) == 1:
		if len(s) == 1:
			if s[0] != '?' and s[0] <= str(k - 1):
				print(s[0])
			elif s[0] != '?' and s[0] > str(k - 1):
				print('NO')
			elif s[0] == '?':
				print(0)
		else:
			print('NO')
	elif k == 2:
		if len(s) % 2 != 0:
			print('NO')
		else:
			cm1 = '01' * (len(s) // 2)
			cm2 = '10' * (len(s) // 2)
			(c1, c2) = (0, 0)
			for i in range(len(s)):
				if s[i] != '?' and s[i] == cm1[i]:
					c1 += 1
				if s[i] != '?' and s[i] == cm2[i]:
					c2 += 1
			if c1 + s.count('?') == len(s):
				print(cm1)
			elif c2 + s.count('?') == len(s):
				print(cm2)
			else:
				print('NO')
	else:
		flag = True
		for i in range(len(s)):
			if s[i] == '?':
				for j in range(0, k):
					if s[i - 1] != str(j) and s[(i + 1) % len(s)] != str(j):
						s[i] = str(j)
						break
			else:
				if s[i - 1] != s[i] and s[i] != s[(i + 1) % len(s)]:
					pass
				else:
					flag = False
					break
				if s[i] > str(k - 1):
					flag = False
					break
		if flag:
			print(''.join(s))
		else:
			print('NO')
